SET.integrations=()=>`<div class="grid gauto">${[['Google Calendar','Two-way booking sync',0],['Google Sheets','Export contacts & bookings',0],['Excel / OneDrive','Import & export',0],['Outlook','Calendar & email',1],['HubSpot','Sync contacts & stages',0],['Salesforce','Sync contacts & deals',0],['Zapier','6,000+ apps',1],['Make','Visual automations',0],['n8n','Self-hosted automations',0],['Stripe','Deposits & invoices',1],['Shopify','Orders & customers',0],['Carrier order system','Create orders at “Order Booked”',1],['Webhooks','Send events to any URL',1],['API keys','Build your own connections',1]].map(x=>`<div class="card pad stack-s" style="padding:16px"><div class="row nw"><span class="av" style="border-radius:8px">${x[0].split(/[ /]/).map(w=>w[0]).join('').slice(0,2)}</span><div><b class="small">${x[0]}</b><div class="xs muted">${x[1]}</div></div></div>${btn(x[2]?'Connected':'Connect','integ',{k:x[2]?'sm':'sm primary',i:x[2]?'check':'',a:`data-n="${esc(x[0])}" data-on="${x[2]}"`})}</div>`).join('')}</div>`;
A.integ=el=>{toast(el.dataset.on==='1'?el.dataset.n+' settings':el.dataset.n+' connected');if(el.dataset.on!=='1'){el.outerHTML=btn('Connected','integ',{k:'sm',i:'check',a:`data-n="${esc(el.dataset.n)}" data-on="1"`})}};
